// why: confirm=false d'abord — tu valides les 3 premières en dashboard, puis tu passes $vars.PRINTFUL_CONFIRM à true
const sbh = { apikey: $vars.SB_SERVICE_KEY, Authorization: `Bearer ${$vars.SB_SERVICE_KEY}`, 'Content-Type': 'application/json' };
const cloth = (await this.helpers.httpRequest({ method: 'GET',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${$input.first().json.body.cloth_id}&select=*`,
  headers: sbh, json: true }))[0];
const variantMap = JSON.parse($vars.PRINTFUL_VARIANT_MAP); // ex: {"default":{"S":4011,"M":4012,"L":4013,"XL":4014}}
const variants = variantMap[cloth.garment_id] || variantMap['default'];
const ship = cloth.shipping?.address || cloth.shipping || {};
const order = await this.helpers.httpRequest({ method: 'POST',
  url: `https://api.printful.com/orders?confirm=${$vars.PRINTFUL_CONFIRM === 'true'}`,
  headers: { Authorization: `Bearer ${$vars.PRINTFUL_KEY}`, 'Content-Type': 'application/json' }, json: true,
  body: {
    external_id: cloth.id,
    recipient: {
      name: cloth.shipping?.name || 'Totehm Member',
      address1: ship.line1, address2: ship.line2 || '',
      city: ship.city, state_code: ship.state || '', country_code: ship.country,
      zip: ship.postal_code, email: cloth.email,
    },
    items: [{ variant_id: variants[cloth.size], quantity: 1, files: [{ type: 'default', url: cloth.artwork_print_url }] }],
  }});
await this.helpers.httpRequest({ method: 'PATCH',
  url: `https://abujjbkbbiumxrokozph.supabase.co/rest/v1/totehm_clothes?id=eq.${cloth.id}`,
  headers: sbh, json: true, body: { status: 'production', printful_order_id: String(order.result.id) } });
return [{ json: { printful_order_id: order.result.id } }];
